"use client"

import type { ComponentProps } from "react"
import { cn } from "cn"
import { Button, type ButtonProps } from "react-aria-components/Button"
import { composeRenderProps } from "react-aria-components/composeRenderProps"
import {
  type DialogProps,
  DialogTrigger,
  type DialogTriggerProps,
  Dialog as RACDialog
} from "react-aria-components/Dialog"
import { Heading, type HeadingProps } from "react-aria-components/Heading"
import { Modal, ModalOverlay, type ModalOverlayProps } from "react-aria-components/Modal"

const Dialog = (props: DialogTriggerProps) => <DialogTrigger {...props} />

interface DialogContentProps
  extends Omit<ModalOverlayProps, "children">,
    Pick<DialogProps, "aria-labelledby" | "role" | "children"> {
  closeButton?: boolean
  overlayClassName?: ModalOverlayProps["className"]
}

function DialogContent({
  className,
  isDismissable: isDismissableInternal,
  children,
  overlayClassName,
  role = "dialog",
  closeButton = true,
  ...props
}: DialogContentProps) {
  const isDismissable = isDismissableInternal ?? role !== "alertdialog"
  return (
    <ModalOverlay
      className={composeRenderProps(overlayClassName, (overlayClassName) =>
        cn(
          "fixed inset-0 isolate z-50 bg-black/10 supports-backdrop-filter:backdrop-blur-xs motion-reduce:backdrop-blur-none",
          "data-entering:fade-in data-entering:animate-in data-entering:ease-out",
          "data-exiting:fade-out data-exiting:animate-out data-exiting:ease-in",
          overlayClassName
        )
      )}
      data-slot="dialog-overlay"
      isDismissable={isDismissable}
      {...props}
    >
      <Modal
        className={composeRenderProps(className, (className) =>
          cn(
            "fixed top-1/2 left-1/2 max-h-[calc(var(--visual-viewport-height)*0.9)] w-full max-w-[min(90vw,450px)] -translate-x-1/2 -translate-y-1/2 text-left align-middle font-sans",
            "inset-shadow rounded-lg border bg-popover bg-clip-padding text-popover-foreground backdrop-blur-sm backdrop-saturate-50",
            "data-entering:zoom-in-95 data-entering:fade-in data-entering:animate-in data-entering:ease-out",
            "data-exiting:zoom-out-95 data-exiting:fade-out data-exiting:animate-out data-exiting:ease-in",
            className
          )
        )}
        data-slot="dialog-content"
      >
        <RACDialog
          aria-label={"Dialog"}
          aria-labelledby={props["aria-labelledby"]}
          className={cn(
            "peer/dialog group/dialog relative flex max-h-[calc(var(--visual-viewport-height)-var(--visual-viewport-vertical-padding))] flex-col overflow-hidden outline-hidden",
            className
          )}
          data-slot="dialog"
          role={role}
        >
          {(values) => (
            <>
              {typeof children === "function" ? children(values) : children}
              {closeButton && <DialogCloseIcon isDismissable={isDismissable} />}
            </>
          )}
        </RACDialog>
      </Modal>
    </ModalOverlay>
  )
}

interface DialogHeaderProps extends Omit<ComponentProps<"div">, "title"> {
  title?: string
  description?: string
}

function DialogHeader({ className, ...props }: DialogHeaderProps) {
  return (
    <div className={cn("relative space-y-1 p-4", className)} data-slot="dialog-header">
      {props.title && <DialogTitle>{props.title}</DialogTitle>}
      {props.description && <DialogDescription>{props.description}</DialogDescription>}
      {!props.title && typeof props.children === "string" ? (
        <DialogTitle>{props.children}</DialogTitle>
      ) : (
        props.children
      )}
    </div>
  )
}

function DialogTitle({ className, ...props }: HeadingProps) {
  return (
    <Heading className={cn("text-balance font-semibold text-foreground text-lg", className)} slot="title" {...props} />
  )
}

function DialogDescription({ className, ...props }: ComponentProps<"div">) {
  return (
    <p
      className={cn("text-pretty text-muted-foreground group-disabled:opacity-50", className)}
      data-slot="description"
      {...props}
    />
  )
}

function DialogBody({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      className={cn(
        "isolate flex min-h-0 flex-1 flex-col overflow-auto px-4 py-1",
        "**:data-[slot=dialog-footer]:px-0 **:data-[slot=dialog-footer]:pt-0",
        className
      )}
      data-slot="dialog-body"
      {...props}
    />
  )
}

function DialogFooter({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      className={cn(
        "isolate mt-auto flex flex-col-reverse justify-end gap-2 p-4 group-not-has-data-[slot=dialog-body]/dialog:pt-0 group-not-has-data-[slot=dialog-body]/popover:pt-0 sm:flex-row",
        className
      )}
      data-slot="dialog-footer"
      {...props}
    />
  )
}

interface CloseButtonIndicatorProps extends Omit<ButtonProps, "children"> {
  className?: string
  isDismissable?: boolean | undefined
}

function DialogCloseIcon({ className, ...props }: CloseButtonIndicatorProps) {
  return props.isDismissable ? (
    <Button
      aria-label="Close dialog"
      className={composeRenderProps(className, (className) =>
        cn(
          "absolute top-2 right-2 isolate z-50 grid size-7 place-content-center rounded-lg hover:bg-secondary focus:bg-secondary focus:outline-hidden focus-visible:ring-1 focus-visible:ring-primary",
          className
        )
      )}
      slot="close"
    >
      <svg height={16} viewBox="0 0 24 24" width={16} xmlns="http://www.w3.org/2000/svg">
        <path
          d="m18 6l-6 6m0 0l-6 6m6-6l6 6m-6-6L6 6"
          fill="none"
          stroke="currentColor"
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeWidth={1.5}
        />
      </svg>
    </Button>
  ) : null
}

Dialog.Body = DialogBody
Dialog.Content = DialogContent
Dialog.Description = DialogDescription
Dialog.Footer = DialogFooter
Dialog.Header = DialogHeader
Dialog.Title = DialogTitle

export { Dialog, DialogBody, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle }
